head.script:
scwin.fireEvent = function(id, event) {
    var dom = WebSquare.wUnit.getDomById($p.id + id);
    if (dom) {
        eval("dom." + event + "();");
    }
}
scwin.fireEvent2 = function(id) {
    var dom = WebSquare.wUnit.getDomById($p.id + id);
    if (dom) {
        grid1.clickRightButtonCell({
            srcElement: dom
        });
    }
}
scwin.draw = function() {
    chart_test_flash.setJSONData(dataObj);
    chart_test_javascript.setJSONData(dataObj1);
}
scwin.fc_test = function() {
    var obj1 = chart_test_flash.fc();
    var obj3 = chart_test_javascript.fc();
    var obj2 = FusionCharts.items["fc_chart_test_flash"];
    var obj4 = FusionCharts.items["fc_chart_test_javascript"];
    if (obj1 == obj2 && obj3 == obj4) {
        return "true";
    } else {
        return "false";
    }
};
scwin.getJSONData_test = function() {
    var chartData = chart_test_flash.getJSONData();
    textarea1.setValue(chartData);
    var chartData1 = chart_test_javascript.getJSONData();
    textarea2.setValue(chartData1);
    return "true";
};
scwin.getDataAsCSV_test = function() {
    var chartData = chart_test_flash.getDataAsCSV();
    textarea1.setValue(chartData);
    var chartData1 = chart_test_javascript.getDataAsCSV();
    textarea2.setValue(chartData1);
    return "true";
};
scwin.setchartAttribute_test = function() {
    var options = {
        "caption": "Half Yearly Revenue Analysis",
        "yaxisname": "Revenue",
        "numberprefix": "$"
    };
    chart_test_flash.setChartAttribute(options);
    chart_test_flash.scwin.draw();
    chart_test_javascript.setChartAttribute(options);
    chart_test_javascript.scwin.draw();
};
scwin.getchartAttribute_test = function() {
    var options = chart_test_flash.getChartAttribute();
    textarea1.setValue(JSON.stringify(options));
    var options1 = chart_test_flash.getChartAttribute();
    textarea2.setValue(JSON.stringify(options1));
    return "true";
};
scwin.setPlotColor_test = function() {
    var color = ["169fe6", "ed5564", "00ba84", "fca651", "8766ca"];
    chart_test_flash.setPlotColor(color);
    chart_test_flash.scwin.draw();
    chart_test_javascript.setPlotColor(color);
    chart_test_javascript.scwin.draw();
    return "true";
};
scwin.addTrendLine_test = function() {
    var options = {
        startValue: "500000",
        color: "FF0000",
        displayValue: "Check"
    };
    chart_test_flash.addTrendLine(options);
    chart_test_flash.scwin.draw();
    chart_test_javascript.addTrendLine(options);
    chart_test_javascript.scwin.draw();
};
scwin.applyStyle_test = function() {
    var options1 = {
        "color": "FF0000",
        "font": "15",
        "bold": "1"
    };
    var options2 = {
        "duration": "2",
        "start": "0",
        "param": "_x"
    };
    //chart_test.applyStyle("font", "captionFont", options1, ["Caption","XAXISNAME"]);
    chart_test_flash.applyStyle("animation", "dataplot_ani", options2, ["dataPlot"]);
    chart_test_javascript.applyStyle("font", "captionFont", options1, ["Caption", "XAXISNAME"]);
};
scwin.configure_test = function() {
    var data = {
        chart: {},
        data: []
    };
    chart_test_flash.fc().setJSONData(data);
    chart_test_flash.configure({
        "ChartNoDataText": "데이타가 없습니다."
    });
    chart_test_flash.fc().render(chart_test_flash.render);
    chart_test_javascript.fc().setJSONData(data);
    chart_test_javascript.configure({
        "ChartNoDataText": "데이타가 없습니다."
    });
    chart_test_javascript.fc().render(chart_test_javascript.render);
};
scwin.dispose = function() {
    chart_test_flash.fc().scwin.dispose();
    chart_test_javascript.fc().scwin.dispose();
};
scwin.test = function() {
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("set", "trigger1.click()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "trigger2.click()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", trigger3.click());
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "chart_test_flash.setAccessibility(true)");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "chart_test_javascript.setAccessibility(true)");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "scwin.getJSONData_test()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "scwin.getDataAsCSV_test()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "scwin.setchartAttribute_test()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("assert", "scwin.getchartAttribute_test()", "true");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("assert", "scwin.setPlotColor_test()", "true");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "scwin.applyStyle_test()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "scwin.addTrendLine_test()");
    WebSquare.wUnit.addCommand("pause", "200");
    WebSquare.wUnit.addCommand("set", "scwin.dispose()");
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
